11	// hugeRevisionJSON is a decimal integer larger than int64 can hold. It is out
12	// of the accepted range on every architecture, so it exercises the raw-token
13	// range rejection end to end without depending on the word size.
14	const hugeRevisionJSON = "99999999999999999999999"
15	
16	// maxAcceptedRevisionJSON is the upper bound accepted by the test binary.
17	func maxAcceptedRevisionJSON() string { return strconv.FormatInt(int64(math.MaxInt), 10) }
18	
19	// decodeRegisterOutput parses one register command output.
20	func decodeRegisterOutput(t *testing.T, out string) registerOutput {
21		t.Helper()
22		var got registerOutput
23		if err := json.Unmarshal([]byte(out), &got); err != nil {
24			t.Fatalf("output is not JSON: %v\n%s", err, out)
25		}
26		return got
27	}
