29	// assertRangeInvalid marks the result as an expectedRevision range rejection:
30	// invalid kind, a reason stating the range and the submitted value, the
31	// service's current revision, and no expected/actual comparison fields.
32	func assertRangeInvalid(t *testing.T, r registerResult, currentRevision int, submitted string) {
33		t.Helper()
34		if r.OK || r.Error != "invalid" {
35			t.Fatalf("want invalid, got %+v", r)
36		}
37		if !strings.Contains(r.Reason, "expectedRevision must be an integer between 0 and") {
38			t.Fatalf("reason should state the expectedRevision range, got %q", r.Reason)
39		}
40		if !strings.Contains(r.Reason, "got "+submitted) {
41			t.Fatalf("reason should report the submitted value %q, got %q", submitted, r.Reason)
42		}
43		if r.Revision != currentRevision {
44			t.Fatalf("revision should report the current revision %d, got %d (%+v)", currentRevision, r.Revision, r)
45		}
46		if !omitsRevisionPair(r) {
47			t.Fatalf("range failure must not report a revision comparison: %+v", r)
48		}
49	}
