82	// TestRegisterExpectedRevisionNegativeRangeReason checks that a negative
83	// revision names the range problem and stays ahead of the revision comparison
84	// for every request kind.
85	func TestRegisterExpectedRevisionNegativeRangeReason(t *testing.T) {
86		input := `{"requests":[
87			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
88			{"type":"register","service":"svc","expectedRevision":-4294967295,"instances":[{"id":"i1","address":"h1:8080"}]},
89			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":-1,"sequence":1,"healthy":true},
90			{"type":"select","service":"svc","expectedRevision":-1},
91			{"type":"select","service":"missing","expectedRevision":-1}
92		]}`
93		out, code := runRegisterWith(t, input)
94		if code != 1 {
95			t.Fatalf("exit code: %d", code)
96		}
97		got := decodeRegisterOutput(t, out)
98		assertRangeInvalid(t, got.Results[1], 1, "-4294967295")
99		assertRangeInvalid(t, got.Results[2], 1, "-1")
100		assertRangeInvalid(t, got.Results[3], 1, "-1")
101		assertRangeInvalid(t, got.Results[4], 0, "-1")
102	}
