153	// TestRegisterExpectedRevisionBoundaries locks the accepted upper bound and
154	// the first rejected integer on the running architecture.
155	func TestRegisterExpectedRevisionBoundaries(t *testing.T) {
156		bound := maxAcceptedRevisionJSON()
157		// The bound itself is a legal integer: for an unknown service it reaches the
158		// revision comparison and conflicts (new services require 0), carrying the
159		// original value rather than a truncated one.
160		input := `{"requests":[{"type":"register","service":"new","expectedRevision":` + bound + `,"instances":[]}]}`
161		out, code := runRegisterWith(t, input)
162		if code != 1 {
163			t.Fatalf("exit code: %d", code)
164		}
165		r := decodeRegisterOutput(t, out).Results[0]
166		if r.OK || r.Error != "conflict" || r.Revision != 0 {
167			t.Fatalf("bound value should reach the revision comparison: %+v", r)
168		}
169		if r.ExpectedRevision == nil || strconv.FormatInt(int64(*r.ExpectedRevision), 10) != bound ||
170			r.ActualRevision == nil || *r.ActualRevision != 0 {
171			t.Fatalf("conflict should preserve expected %s and explicit actual 0, got %+v", bound, r)
172		}
173	
174		// One more than the bound is invalid on every architecture. On 64-bit that
175		// value also exceeds int64, so it arrives through the raw-text path; it is
176		// computed in uint64 to avoid overflowing the comparison itself.
177		boundN, err := strconv.ParseUint(bound, 10, 64)
178		if err != nil {
179			t.Fatalf("parse bound: %v", err)
180		}
181		over := strconv.FormatUint(boundN+1, 10)
182		input = `{"requests":[{"type":"select","service":"s","expectedRevision":` + over + `}]}`
183		out, code = runRegisterWith(t, input)
