190	// TestRegisterOutOfRangeRevisionBatchIsolation is the end-to-end regression
191	// guard for the 32-bit wrapping values. Out-of-range items keep their slots as
192	// invalid rejections; they create nothing, replace nothing, write no health,
193	// return no target, move no cursor and bind no session. Later valid requests
194	// run against the pre-rejection state and the existing rotation/session rules.
195	func TestRegisterOutOfRangeRevisionBatchIsolation(t *testing.T) {
196		if strconv.IntSize != 32 {
197			// int64 cannot hold a value that overflows 64-bit int; the word-size
198			// independent overflow path is covered by TestRegisterExpectedRevisionBeyondInt64.
199			t.Skip("wrapping int64 values only exist on a 32-bit build")
200		}
201		const wrapPositive = "4294967297" // wraps to 1
202		const wrapNegative = "-4294967295"
203		input := `{"requests":[
204			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
205			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":` + wrapPositive + `,"sequence":1,"healthy":true},
206			{"type":"register","service":"svc","expectedRevision":` + wrapNegative + `,"instances":[{"id":"i1","address":"h2:9090"}]},
207			{"type":"select","service":"svc","expectedRevision":` + wrapPositive + `},
208			{"type":"select","service":"svc","expectedRevision":` + wrapPositive + `,"sessionKey":"s"},
209			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":1,"healthy":true},
210			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s"},
211			{"type":"select","service":"svc","expectedRevision":1}
212		]}`
213		out, code := runRegisterWith(t, input)
214		if code != 1 {
215			t.Fatalf("batch contains failures, exit code: %d, output: %s", code, out)
216		}
217		got := decodeRegisterOutput(t, out)
218		if len(got.Results) != 8 {
219			t.Fatalf("results: %+v", got.Results)
220		}
221		// 0: create.
222		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
223			t.Fatalf("result 0: %+v", r)
224		}
225		// 1-4: every wrapping value is an invalid range rejection at revision 1,
226		// never a conflict/not_found, carrying no target or comparison fields.
227		for i, submitted := range []string{wrapPositive, wrapNegative, wrapPositive, wrapPositive} {
228			r := got.Results[i+1]
229			assertRangeInvalid(t, r, 1, submitted)
230			if r.InstanceID != "" || r.Address != "" {
231				t.Fatalf("result %d must fabricate no target: %+v", i+1, r)
232			}
233		}
234		// 5: the rejected health wrote nothing; this valid report is the first
235		// observation and lands at sequence 1.
236		if r := got.Results[5]; !r.OK || !r.Changed || r.Sequence != 1 || r.Revision != 1 {
237			t.Fatalf("result 5 valid health: %+v", r)
238		}
239		// 6: the failed item 4 never bound "s", so this first success rotates to the
240		// smallest healthy id (i1) and binds now.
241		if r := got.Results[6]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 1 {
242			t.Fatalf("result 6 first session select: %+v", r)
243		}
244		// 7: the rejected selects moved no cursor; with i1 the only healthy
245		// instance it is chosen again, and the rejected replacement never changed
246		// the address to h2:9090.
247		if r := got.Results[7]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" {
248			t.Fatalf("result 7: %+v", r)
249		}
250		// Final snapshot: revision 1, i1 at its original address healthy at 1, i2
251		// still unknown at its original address.
252		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
253			t.Fatalf("services: %+v", got.Services)
254		}
255		insts := got.Services[0].Instances
256		if len(insts) != 2 {
257			t.Fatalf("instances: %+v", insts)
258		}
259		if insts[0].ID != "i1" || insts[0].Address != "h1:8080" || insts[0].Health != "healthy" || insts[0].Sequence != 1 {
260			t.Fatalf("i1 state: %+v", insts[0])
261		}
262		if insts[1].ID != "i2" || insts[1].Address != "h2:8080" || insts[1].Health != "unknown" {
263			t.Fatalf("i2 state: %+v", insts[1])
264		}
265	}
266	
267	// TestRegisterOutOfRangeFieldPrecedence locks where the range rejection sits
268	// relative to the other field checks.
269	//
270	// A value that parses as int64 (the reported 4294967297 and negatives) reaches
271	// the registry, so the long-standing field order applies on every
272	// architecture: service name and instance id are checked before the revision
273	// range, and an explicit null/non-string sessionKey is rejected in the handler
274	// before anything else. The 32-bit-only subtest adds that, on a 32-bit build,
275	// the out-of-range revision is judged before the remaining content fields and
276	// the revision conflict, since it is still a field check.
277	//
278	// A token that cannot even be carried as int64 (the huge value) fails at the
279	// handler's raw-token parse, the same tier that rejects float/string revision
280	// tokens; TestRegisterExpectedRevisionBeyondInt64 covers it.
281	func TestRegisterOutOfRangeFieldPrecedence(t *testing.T) {
282		const overflow32 = "4294967297" // parses as int64; exceeds int only on 32-bit
283	
284		// Earlier-checked fields win on every architecture (on 64-bit the value is
285		// in range, but the name/id checks still precede the revision comparison).
286		out, code := runRegisterWith(t, `{"requests":[
287			{"type":"register","service":"  ","expectedRevision":`+overflow32+`,"instances":[]},
288			{"type":"health","service":"svc","instanceId":" ","expectedRevision":`+overflow32+`,"sequence":1,"healthy":true},
289			{"type":"select","service":"  ","expectedRevision":`+overflow32+`},
290			{"type":"select","service":"svc","expectedRevision":`+overflow32+`,"sessionKey":null}
291		]}`)
292		if code != 1 {
293			t.Fatalf("exit code: %d", code)
294		}
295		got := decodeRegisterOutput(t, out)
296		want := []string{
297			"service name must not be empty",
298			"instance id must not be empty",
299			"service name must not be empty",
300			"sessionKey must be a string, not null",
301		}
302		for i, sub := range want {
303			r := got.Results[i]
304			if r.OK || r.Error != "invalid" || !strings.Contains(r.Reason, sub) {
305				t.Fatalf("result %d: want invalid containing %q, got %+v", i, sub, r)
306			}
307			if !omitsRevisionPair(r) {
308				t.Fatalf("result %d must not report a revision comparison: %+v", i, r)
309			}
310		}
311	
312		// Same ordering for a parsable negative, on every architecture.
313		out, code = runRegisterWith(t, `{"requests":[
314			{"type":"register","service":"  ","expectedRevision":-1,"instances":[]},
315			{"type":"health","service":"svc","instanceId":" ","expectedRevision":-1,"sequence":1,"healthy":true}
316		]}`)
317		if code != 1 {
318			t.Fatalf("exit code: %d", code)
319		}
320		got = decodeRegisterOutput(t, out)
321		for i, sub := range []string{"service name must not be empty", "instance id must not be empty"} {
322			if r := got.Results[i]; r.OK || r.Error != "invalid" || !strings.Contains(r.Reason, sub) {
323				t.Fatalf("negative result %d: %+v", i, r)
324			}
325		}
326	
327		if strconv.IntSize != 32 {
328			return
329		}
330	
331		// On 32-bit the parsable value is out of range: it beats the remaining
332		// content fields and the revision conflict, at the service's revision 1.
333		out, code = runRegisterWith(t, `{"requests":[
334			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
335			{"type":"register","service":"svc","expectedRevision":`+overflow32+`,"instances":[{"id":"","address":"h1:8080"}]},
336			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":`+overflow32+`,"sequence":0,"healthy":true},
337			{"type":"select","service":"svc","expectedRevision":`+overflow32+`},
338			{"type":"select","service":"missing","expectedRevision":`+overflow32+`}
339		]}`)
340		if code != 1 {
341			t.Fatalf("exit code: %d", code)
342		}
343		got = decodeRegisterOutput(t, out)
344		for i, current := range []int{1, 1, 1, 0} {
345			r := got.Results[i+1]
346			assertRangeInvalid(t, r, current, overflow32)
347		}
348	}
349	
350	// TestRegisterLargeInRangeRevisionOn64Bit locks that the fix does not clamp
351	// 64-bit builds to the 32-bit bound: 2147483648 is a legal integer on 64-bit
352	// and yields an ordinary conflict against a revision-1 service while
353	// preserving the submitted value. On 32-bit it is rejected as out of range.
354	func TestRegisterLargeInRangeRevisionOn64Bit(t *testing.T) {
355		const large = "2147483648"
356		input := `{"requests":[
357			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
358			{"type":"register","service":"svc","expectedRevision":` + large + `,"instances":[]},
359			{"type":"select","service":"svc","expectedRevision":` + large + `}
360		]}`
361		out, code := runRegisterWith(t, input)
362		if code != 1 {
363			t.Fatalf("exit code: %d", code)
364		}
365		got := decodeRegisterOutput(t, out)
366		if strconv.IntSize == 32 {
367			assertRangeInvalid(t, got.Results[1], 1, large)
368			assertRangeInvalid(t, got.Results[2], 1, large)
369			return
370		}
371		wantExpected, err := strconv.Atoi(large)
372		if err != nil {
373			t.Fatalf("parse %s: %v", large, err)
374		}
375		for i := 1; i <= 2; i++ {
376			r := got.Results[i]
377			if r.OK || r.Error != "conflict" ||
378				!hasRevisionPair(r, wantExpected, 1) || r.Revision != 1 {
379				t.Fatalf("result %d should be a normal conflict preserving %s: %+v", i, large, r)
380			}
381		}
382	}
